      const paperText=`${next.author} (${next.year}) · Fig. ${next.figure} · ${next.pageLabel||'p.'} ${next.page}`;
      $('museumSource').textContent=paperText+' · ';
      $('museumSourceLinks').replaceChildren();
      const preferred=next.sources.find(s=>s.open)||next.sources[0];
      for(const source of next.sources){const a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener';a.textContent=source.label+' ↗';$('museumSourceLinks').append(a);if(source===preferred){const short=a.cloneNode(true);short.textContent=source.open?'Open paper ↗':'Original paper ↗';$('museumSource').append(short);}}
      root.MuseumPresentation.show(next);
      $('museumParameters').textContent=studies.extra(next)?paperText:next.kind==='field'?`${next.family==='N'?'Electric N':'Magnetic M'}${next.n} · live unit-sphere view`:next.kind==='gold'?'Gold in water · electric dipole · historical optical constants':`Paper: x = ${next.x}, m = ${next.m===4/3?'4/3':next.m} · live 3D far field`;
      if(next.dotsenko)$('museumKey').textContent=next.dotsenkoMap?'D65-weighted contours · click the map or adjust core radius and shell thickness':'Left: Q_sca · right: g · six colours identify shell thickness';else if(next.kind==='book')$('museumKey').textContent='App Mie / population curves · select a curve to inspect its settings';else if(next.kind!=='shell')$('museumKey').textContent=next.kind==='field'?'Colour |F|² · white-edged arrows: Re F direction · drag to rotate':next.kind==='polar'?'Paper scale: separate i₁ / i₂ · 3D view: polarized E ∥ x':next.kind==='dimer'?'App dimer absorption · absolute µW per sphere':next.kind==='transmission'?'App Rayleigh + Beer–Lambert · slide relative path L':next.kind==='rayleigh'?'App Rayleigh scattering · relative intensity versus wavelength':'Nine app spectra · select a curve to inspect its Paper settings';
      const metric=(label,value,note)=>`<div class="metric"><span>${label}</span><b>${value}</b><small>${note}</small></div>`;
      $('metrics').innerHTML=metric('Paper',next.year,next.author)+metric('Figure',next.figure,`${next.pageLabel||'printed p.'} ${next.page}`)+metric('App view',next.kind==='field'?`${next.family}${next.n}`:next.kind==='gold'?'a₁':simulation.lesson||'Full Mie','same laboratory solvers');
